  for(const part of header.split(';')){
    const i=part.indexOf('=');
    if(i<0)continue;
    if(part.slice(0,i).trim()===SESSION_COOKIE){try{return decodeURIComponent(part.slice(i+1).trim())||null}catch{return null}}
  }
